# Mock classes for testing
class Patient:
    def __init__(self, age, conditions=None, severities=None):
        self.age = age
        self._conditions = conditions if conditions is not None else []
        self._severities = severities if severities is not None else []

    def get_total_conditions(self):
        return len(self._conditions)

    def get_average_severity(self):
        if not self._severities:
            return 0.0
        return sum(self._severities) / len(self._severities)

class Hospital:
    def __init__(self, patients, records):
        self.patients = patients  # dict patient_id:Patient
        self.records = records    # dict patient_id: [ { 'vitals': ... } ] (last 90 days etc.)

    def get_patient(self, patient_id):
        return self.patients[patient_id]

    def get_recent_records(self, patient_id, days):
        return self.records.get(patient_id, [])

def dummy_recent_records(normal=True, count=1):
    "Return list of vitals dicts, with 'abnormal' key True/False."
    if normal:
        return [{'vitals': {'abnormal': False}} for _ in range(count)]
    else:
        return [{'vitals': {'abnormal': True}} for _ in range(count)]

def any_abnormal(records):
    # Helper: returns True if any vital record in list is abnormal
    return any(rec.get('vitals', {}).get('abnormal', False) for rec in records)

def patient_risk_score(hospital, patient_id):
    '''
    Create a function called patient_risk_score that takes a Hospital object and patient_id. Calculate risk score using formula: (patient.age / 100 * 30) + (patient.get_total_conditions() * 5 * 25/100) + (patient.get_average_severity() * 10 * 25/100) + (20 if recent records have abnormal vitals else 0). Use hospital.get_patient(patient_id) and hospital.get_recent_records(patient_id, 90). Returns: float between 0.0 and 100.0.
    '''
    patient = hospital.get_patient(patient_id)
    recent_records = hospital.get_recent_records(patient_id, 90)
    age_score = (patient.age / 100) * 30
    cond_score = (patient.get_total_conditions() * 5) * (25 / 100)
    severity_score = (patient.get_average_severity() * 10) * (25 / 100)
    abnormal = any_abnormal(recent_records)
    vitals_score = 20 if abnormal else 0
    risk_score = age_score + cond_score + severity_score + vitals_score
    # Clamp between 0 and 100
    return min(100.0, max(0.0, round(risk_score, 2)))

