class DummyUniversity:
    def __init__(self, enrollments_by_student, courses):
        self.enrollments_by_student = enrollments_by_student
        self.courses = courses
    def get_student_enrollments(self, student_id):
        return self.enrollments_by_student[student_id]
    def get_course(self, course_code):
        return self.courses[course_code]

def calculate_simple_gpa(university, student_id):
    '''
    Create a function called calculate_simple_gpa that takes a University object and student_id. For each enrollment from university.get_student_enrollments(student_id), get the course using university.get_course(enrollment.course_code), multiply enrollment.get_grade_points() by course.credits, sum all points and credits, return total_points / total_credits as GPA (0.0-4.0).
    '''
    enrollments = university.get_student_enrollments(student_id)
    total_points = 0
    total_credits = 0
    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        grade_points = enrollment.get_grade_points()
        credits = course.credits
        total_points += grade_points * credits
        total_credits += credits
    if total_credits == 0:
        return 0.0
    return total_points / total_credits

