        return self._grade_points

class Course:
    def __init__(self, code, credits):
        self.code = code
        self.credits = credits

class University:
    def __init__(self):
        self._students = {}
        self._courses = {}

    def add_course(self, course):
        self._courses[course.code] = course

    def add_student_enrollment(self, student_id, enrollment):
        self._students.setdefault(student_id, []).append(enrollment)

    def get_student_enrollments(self, student_id):
        return self._students.get(student_id, [])

    def get_course(self, course_code):
        return self._courses.get(course_code)


def calculate_simple_gpa(university, student_id):
    enrollments = university.get_student_enrollments(student_id)
    total_points = 0.0
    total_credits = 0.0
    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        if course is not None:
            points = enrollment.get_grade_points() * course.credits
            total_points += points
            total_credits += course.credits
    return round(total_points / total_credits, 3) if total_credits > 0 else 0.0


